INSERT INTO drink_categories ( drink_category_id, shop_id, category_name, is_deleted ) SELECT gen_random_uuid(), #{request.shopId}, TRIM(#{request.categoryName}), false WHERE EXISTS ( SELECT 1 FROM shops s WHERE s.shop_id = #{request.shopId} AND s.deleted_at IS NULL )
AND #{request.shopId} = #{currentUserShopId}
AND 1 = 0
